input.command:
python -B -X utf8 -c 'import csv,json,zipfile,posixpath; from decimal import Decimal; from pathlib import Path; import xml.etree.ElementTree as E; ns={"s":"http://schemas.openxmlformats.org/spreadsheetml/2006/main"}; p=Path("deliverables/销售核对.xlsx"); rows=list(csv.DictReader(Path("sales.csv").open(encoding="utf-8-sig",newline=""))); print("WORKDIR",str(Path.cwd())); print("CSV",json.dumps(rows,ensure_ascii=False)); z=zipfile.ZipFile(p,"r"); strings=[]; strings_path="xl/sharedStrings.xml"; strings=["".join(t.text or "" for t in si.iter("{"+ns["s"]+"}t")) for si in E.fromstring(z.read(strings_path))] if strings_path in z.namelist() else []; rels={r.attrib["Id"]:r.attrib["Target"] for r in E.fromstring(z.read("xl/_rels/workbook.xml.rels"))}; wb=E.fromstring(z.read("xl/workbook.xml")); sheets={}; rid="{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id";
for sheet in wb.find("s:sheets",ns):
 target=rels[sheet.attrib[rid]]; target=target.lstrip("/") if target.startswith("/") else posixpath.normpath(posixpath.join("xl",target)); root=E.fromstring(z.read(target)); out=[]
 for row in root.findall("s:sheetData/s:row",ns):
  cells=[]
  for c in row.findall("s:c",ns):
   typ=c.get("t","n"); v=c.find("s:v",ns); raw=v.text if v is not None else None; inline=c.find("s:is",ns); value="".join(t.text or "" for t in inline.iter("{"+ns["s"]+"}t")) if typ=="inlineStr" and inline is not None else strings[int(raw)] if typ=="s" else (raw=="1") if typ=="b" else raw; cells.append({"cell":c.get("r"),"type":typ,"value":value,"formula":c.findtext("s:f",default=None,namespaces=ns),"style":c.get("s")})
  out.append(cells)
 sheets[sheet.attrib["name"]]=out
print("SHEETS",json.dumps(sheets,ensure_ascii=False)); regions={}
for r in rows:
 a=Decimal(r["金额"]); d=regions.setdefault(r["区域"],{"count":0,"amount":Decimal(0)}); d["count"]+=1; d["amount"]+=a
print("CSV_INDEPENDENT",json.dumps({"count":len(rows),"amount":str(sum((Decimal(r["金额"]) for r in rows),Decimal(0))),"regions":{k:{"count":v["count"],"amount":str(v["amount"])} for k,v in regions.items()},"refunds":sum(Decimal(r["金额"])<0 for r in rows),"zeros":sum(Decimal(r["金额"])==0 for r in rows)},ensure_ascii=False)); z.close()'

